import numpy as np
from scipy.optimize import least_squares
V=np.var(dA_dt)
forms={
 'A_prod': (lambda p,t: p[0]*(1-np.exp(-p[1]*t))*np.exp(-p[2]*t)+p[3]*t, [6,1,0.05,0.1]),
 'C_rat': (lambda p,t: p[0]*t**p[1]/(1+p[2]*t**p[1]), [7,1,0.3]),
 'D_pow': (lambda p,t: p[0]*(1-np.exp(-p[1]*t))**p[2]*np.exp(-p[3]*t), [6,1,1,0.02]),
 'F_rat': (lambda p,t: p[0]*(1-np.exp(-p[1]*t))/(1+p[2]*t), [7,1,0.05]),
 'G_mix': (lambda p,t: p[0]*t/(p[1]+t)+p[2]*t*np.exp(-p[3]*t), [6,1,0.5,0.1]),
 'H_mix': (lambda p,t: p[0]*(1-np.exp(-p[1]*t))+p[2]*t*np.exp(-p[3]*t)+p[4]*(1-np.exp(-p[5]*t)), [5,1,0.5,0.1,1,1]),
 'I_gam': (lambda p,t: p[0]*t**p[1]*np.exp(-p[2]*t)+p[3], [5,0.5,0.1,1]),
 'J_tanh': (lambda p,t: p[0]*np.tanh(p[1]*t)+p[2]*t*np.exp(-p[3]*t), [6,0.7,0.5,0.1]),
}
for name,(f,p0) in forms.items():
    def model(p,t,A):
        a=f(p[:len(p0)],t)
        b=p[-2]*np.exp(-p[-1]*t)
        return a+b*A**3
    pp=list(p0)+[0.17,0.095]
    best=None
    for trial in range(3):
        start=np.array(pp)*(1+0.2*trial*np.random.randn(len(pp))) if trial>0 else np.array(pp)
        try:
            r=least_squares(lambda p: model(p,t,A)-dA_dt, start, method='lm', max_nfev=3000)
            v=np.mean(r.fun**2)/V
            if np.isfinite(v) and (best is None or v<best[0]): best=(v,r.x)
        except Exception as e: pass
    if best: print(name, "NMSE %.3e"%best[0], np.round(best[1],4))
    else: print(name,"fail")

